import type { PrismaClient } from "@prisma/client";
import { createTrip } from "../../src/lib/trip/generate";
import { findCity } from "./locations";

/**
 * Sample itineraries generated by the real planner. Places come from the POI cache
 * (fill it with `npx tsx scripts/poi-warm.ts`); without cached hotels the planner uses its
 * labelled stay estimates. Runs with POI_OFFLINE=1 unless SEED_LIVE_POI=1.
 */
const TRIPS = [
  { email: "aarav@nira.app", city: ["CH", "Zürich"], title: "Zürich long weekend", days: 3, people: 2, budget: 1800, currency: "CHF", style: "BALANCED", pace: "NORMAL", interests: ["CULTURE", "NATURE", "FOOD"] },
  { email: "priya@nira.app", city: ["CH", "Genève"], title: "Geneva on a student budget", days: 2, people: 1, budget: 450, currency: "CHF", style: "BUDGET", pace: "RELAXED", interests: ["NATURE", "CULTURE"] },
  { email: "lena@nira.app", city: ["CH", "Lausanne"], title: "Lausanne lake days", days: 3, people: 2, budget: 2200, currency: "CHF", style: "COMFORT", pace: "PACKED", interests: ["FOOD", "NIGHTLIFE", "NATURE"] },
] as const;

export async function seedTrips(prisma: PrismaClient) {
  if (process.env.SEED_LIVE_POI !== "1") process.env.POI_OFFLINE = "1";
  let made = 0;
  for (const t of TRIPS) {
    const user = await prisma.user.findUnique({ where: { email: t.email }, select: { id: true } });
    if (!user) continue;
    if (await prisma.itinerary.findFirst({ where: { userId: user.id, title: t.title }, select: { id: true } })) continue;
    const city = await findCity(prisma, t.city[0], t.city[1]);
    try {
      await createTrip(user.id, {
        cityId: city.id, title: t.title, days: t.days, people: t.people, budget: t.budget, currency: t.currency,
        style: t.style, pace: t.pace, stayPreference: "ANY", interests: [...t.interests], startDate: null,
      });
      made++;
    } catch (err) {
      console.warn(`  skipped "${t.title}": ${(err as Error).message}`);
    }
  }
  console.log(`  sample itineraries: +${made}`);
}
